package com.ova.aac3oggjx;
import android.app.Activity;import android.app.AlertDialog;import android.os.Bundle;import android.os.Message;import android.content.Intent;import android.webkit.*;
public class MainActivity extends Activity{
WebView w;
void open(android.net.Uri u){try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){}}
class Br{@JavascriptInterface public void open(final String u){runOnUiThread(new Runnable(){public void run(){MainActivity.this.open(android.net.Uri.parse(u));}});}@JavascriptInterface public void copy(final String t){runOnUiThread(new Runnable(){public void run(){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(android.content.ClipData.newPlainText("t",t));android.widget.Toast.makeText(MainActivity.this,"OK",android.widget.Toast.LENGTH_SHORT).show();}});}@JavascriptInterface public void share(final String t){runOnUiThread(new Runnable(){public void run(){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,t);startActivity(Intent.createChooser(i,null));}});}}
@Override protected void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);setContentView(w);w.setFitsSystemWindows(true);w.addJavascriptInterface(new Br(),"OvaApp");w.setOverScrollMode(WebView.OVER_SCROLL_NEVER);w.setHorizontalScrollBarEnabled(false);w.setVerticalScrollBarEnabled(false);w.setBackgroundColor(0xFF050B18);WebSettings s=w.getSettings();s.setTextZoom(100);s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setSupportMultipleWindows(true);s.setJavaScriptCanOpenWindowsAutomatically(true);
w.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if("file".equals(r.getUrl().getScheme()))return false;open(r.getUrl());return true;}});
w.setWebChromeClient(new WebChromeClient(){
@Override public boolean onJsAlert(WebView v,String u,String m,final JsResult r){new AlertDialog.Builder(MainActivity.this).setMessage(m).setPositiveButton("OK",(d,i)->r.confirm()).setOnCancelListener(d->r.cancel()).show();return true;}
@Override public boolean onCreateWindow(WebView v,boolean d,boolean g,Message m){WebView t=new WebView(MainActivity.this);t.setWebViewClient(new WebViewClient(){@Override public void onPageStarted(WebView x,String u,android.graphics.Bitmap b){open(android.net.Uri.parse(u));x.stopLoading();}@Override public boolean shouldOverrideUrlLoading(WebView x,WebResourceRequest r){open(r.getUrl());return true;}});((WebView.WebViewTransport)m.obj).setWebView(t);m.sendToTarget();return true;}});
w.loadUrl("file:///android_asset/www/index.html");}
@Override public void onBackPressed(){w.evaluateJavascript("window.ovaBack&&window.ovaBack()",new ValueCallback<String>(){public void onReceiveValue(String v){if(!"true".equals(v))finish();}});}
}
